import { Capacitor, registerPlugin } from '@capacitor/core'

interface DownloadsSaverPlugin {
  saveImageFile(options: { name: string; data: string; mimeType: string }): Promise<{ location: string }>
}

const DownloadsSaver = registerPlugin<DownloadsSaverPlugin>('DownloadsSaver')
const QR_FILE_NAME = '随手记-作者微信二维码.png'

/** 保存作者二维码：Android 写入公共下载目录，网页版交给浏览器下载。 */
export async function saveWechatQrCode(assetUrl: string): Promise<{ location?: string }> {
  if (!Capacitor.isNativePlatform()) {
    const anchor = document.createElement('a')
    anchor.href = assetUrl
    anchor.download = QR_FILE_NAME
    anchor.click()
    return {}
  }

  const response = await fetch(assetUrl)
  if (!response.ok) throw new Error('二维码读取失败，请稍后重试')
  const blob = await response.blob()
  const dataUrl = await new Promise<string>((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(String(reader.result))
    reader.onerror = () => reject(new Error('二维码读取失败，请稍后重试'))
    reader.readAsDataURL(blob)
  })
  const comma = dataUrl.indexOf(',')
  if (comma < 0) throw new Error('二维码格式异常，请稍后重试')
  const result = await DownloadsSaver.saveImageFile({
    name: QR_FILE_NAME,
    data: dataUrl.slice(comma + 1),
    mimeType: blob.type || 'image/png',
  })
  return { location: result.location }
}
