<script setup lang="ts">
import { Check, RefreshCw } from '@lucide/vue'
import { computed } from 'vue'
import AppDialog from './AppDialog.vue'

export type UpdatePhase = 'connecting' | 'checking' | 'discovered' | 'downloading' | 'success' | 'current'

const props = withDefaults(defineProps<{
  open: boolean
  phase: UpdatePhase
  /** 下载百分比 0-100；null = 平台不提供进度（PWA/APK 通道），显示无百分比的"下载中…" */
  progress?: number | null
  /** 新版本号（discovered 阶段展示） */
  version?: string
}>(), { progress: null, version: '' })

const emit = defineEmits<{ close: [] }>()

const phases = [
  { key: 'connecting', label: '已连接网络' },
  { key: 'checking', label: '正在检查中' },
  { key: 'discovered', label: '发现新版本' },
  { key: 'downloading', label: '新版本下载中' },
  { key: 'success', label: '下载成功' },
] as const

const currentIndex = computed(() => phases.findIndex((step) => step.key === props.phase))

/** 中间加粗大标题：跟随阶段实时变化（参考图"正在打包与发布架构资产…"的位置） */
const statusTitle = computed(() => {
  switch (props.phase) {
    case 'connecting': return '已连接网络…'
    case 'checking': return '正在检查中…'
    case 'discovered': return props.version ? `发现新版本 ${props.version}` : '发现新版本'
    case 'downloading': return props.progress == null ? '下载中…' : `下载中 ${Math.round(props.progress)}%`
    case 'success': return '下载成功'
    default: return ''
  }
})

/** 进度条与百分比仅在拿到真实进度时展示（PWA/APK 通道无进度，不显示 0% 空条） */
const hasProgress = computed(() => typeof props.progress === 'number')

/** 成功阶段的补充说明（提示断网与刷新方式） */
const successHint = '已主动断开网络，放心使用。\n请下拉刷新页面或重新打开 App。'

const closeLabel = computed(() => (props.phase === 'success' || props.phase === 'current' ? '我知道了' : '放弃更新'))

/** 图标动画：非成功阶段持续旋转，成功阶段停转打勾 */
const spinning = computed(() => props.phase !== 'success' && props.phase !== 'current')
</script>

<template>
  <AppDialog :open="open" position="center" title="检查更新" @close="emit('close')">
    <div class="update-progress">
      <span class="status-icon" :class="{ done: phase === 'success' || phase === 'current' }">
        <Check v-if="phase === 'success' || phase === 'current'" :size="30" aria-hidden="true" />
        <RefreshCw v-else :size="30" :class="{ spinning }" aria-hidden="true" />
      </span>
      <p class="status-title">{{ phase === 'success' ? '下载成功' : phase === 'current' ? '当前已是最新版本' : statusTitle }}</p>
      <p v-if="phase === 'current'" class="current-hint">当前版本已是最新版本，无需更新。</p>
      <ol v-else class="steps">
        <li
          v-for="(step, index) in phases"
          :key="step.key"
          :class="{ done: index < currentIndex || phase === 'success', active: index === currentIndex && phase !== 'success' }"
        >
          <span class="index">{{ index < currentIndex || phase === 'success' ? '✓' : `${index + 1}` }}</span>
          <span class="label">{{ step.label }}</span>
          <span v-if="step.key === 'downloading' && phase === 'downloading' && hasProgress" class="percent">{{ Math.round(progress ?? 0) }}%</span>
        </li>
      </ol>
      <div
        v-if="hasProgress && (phase === 'downloading' || phase === 'success')"
        class="progress-track"
        :aria-valuenow="Math.round(progress ?? 0)"
        aria-valuemin="0"
        aria-valuemax="100"
        role="progressbar"
      >
        <div class="progress-fill" :class="{ full: phase === 'success' }" :style="{ width: `${phase === 'success' ? 100 : Math.min(100, Math.max(0, progress ?? 0))}%` }" />
      </div>
      <p v-if="phase === 'success'" class="success-hint">{{ successHint }}</p>
    </div>
    <template #actions>
      <button class="button primary" type="button" @click="emit('close')">{{ closeLabel }}</button>
    </template>
  </AppDialog>
</template>

<style scoped>
.update-progress { display: grid; justify-items: center; padding: 6px 0 2px; }
.status-icon { display: grid; width: 56px; height: 56px; place-items: center; border-radius: 18px; background: var(--color-primary-soft); color: var(--color-primary); margin-bottom: 10px; }
.status-icon.done { background: var(--color-success-soft, #e8f7ee); color: var(--color-success, #16a34a); }
.status-title { margin: 0 0 14px; font-size: 17px; font-weight: 700; text-align: center; }
.steps { list-style: none; width: 100%; padding: 10px 14px; margin: 0 0 12px; display: grid; gap: 9px; background: var(--color-bg-secondary, #f5f7fb); border-radius: var(--radius-md); box-sizing: border-box; }
.steps li { display: flex; align-items: center; gap: 10px; color: var(--color-text-tertiary); font-size: 13.5px; transition: color 0.25s ease; }
.steps li.done { color: var(--color-text-secondary); }
.steps li.active { color: var(--color-primary); font-weight: 600; }
.index { display: grid; width: 20px; height: 20px; place-items: center; flex-shrink: 0; border-radius: 50%; border: 1.5px solid currentColor; font-size: 11px; font-weight: 600; font-variant-numeric: tabular-nums; }
.steps li.done .index { background: var(--color-primary); border-color: var(--color-primary); color: white; }
.percent { margin-left: auto; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--color-primary); }
.progress-track { width: 100%; height: 8px; background: var(--color-bg-secondary, #eef1f6); border-radius: 4px; overflow: hidden; }
.progress-fill { height: 100%; border-radius: 4px; background: var(--color-primary); transition: width 0.3s ease; }
.progress-fill.full { background: var(--color-success, #16a34a); }
.success-hint { margin: 12px 0 0; color: var(--color-text-secondary); font-size: 13px; text-align: center; white-space: pre-line; line-height: 1.6; }
.current-hint { margin: 0 0 8px; color: var(--color-text-secondary); font-size: 14px; text-align: center; }
.spinning { animation: spin 1s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
@media (prefers-reduced-motion: reduce) { .spinning { animation: none; } }
</style>
